import{_ as s,o as n,c as e,a6 as p}from"./chunks/framework.B_q3ZJNF.js";const u=JSON.parse('{"title":"构建期与运行期的分界：索引卡片与书","description":"","frontmatter":{"title":"构建期与运行期的分界：索引卡片与书"},"headers":[],"relativePath":"vscode-iconify-course/07-build-vs-runtime.md","filePath":"vscode-iconify-course/docs/07-build-vs-runtime.md"}'),t={name:"vscode-iconify-course/07-build-vs-runtime.md"};function i(o,a,r,l,c,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="构建期与运行期的分界-索引卡片与书" tabindex="-1">构建期与运行期的分界：索引卡片与书 <a class="header-anchor" href="#构建期与运行期的分界-索引卡片与书" aria-label="Permalink to &quot;构建期与运行期的分界：索引卡片与书&quot;">​</a></h1><p>一个团队内部分发图标扩展时走了两个极端。第一版追求「开箱即用、完全离线」，把全部图标集合的数据打进扩展包，安装包从 2MB 涨到 100MB，内网市场直接拒收；第二版矫枉过正，什么都运行时再取，结果断网的日子里插件全瞎——补全列表里只剩光秃秃的集合名，装饰一个都不亮，连昨天明明看过的图标也翻脸不认。两版的分歧其实是一个问题：<strong>数据在什么时刻、以什么形态，呆在什么位置</strong>。这一章不写代码，把这笔账算清楚——它是前两章缓存与渲染背后没说破的设计前提。</p><h2 id="两类数据-两种命运" tabindex="-1">两类数据，两种命运 <a class="header-anchor" href="#两类数据-两种命运" aria-label="Permalink to &quot;两类数据，两种命运&quot;">​</a></h2><p>图标智能用到的数据分两类，重量差了三个数量级。</p><p><strong>元数据</strong>：每个集合的 id、显示名、授权信息，以及一份图标名清单——只有名字，没有图形。整个图标世界加起来，这份清单也就几 MB 量级。它的消费者是「不需要看图」的逻辑：第 2 章的正则要拿集合 id 做交替分支，第 4 章的解析要拿它消歧，第 9 章的补全要拿图标名清单出候选。这些逻辑全是同步的、每次按键都可能跑的，数据必须常驻内存。</p><p><strong>完整数据</strong>：每个集合的 SVG 绘制片段，单集合几百 KB 到几 MB，全部集合上百 MB。它的消费者只有渲染——真的要画某个图标的那一刻。这一刻在用户编辑过程中稀疏地出现。</p><p>重量差三个数量级、消费时机差了几个数量级，答案就自然了：<strong>元数据构建期打包，完整数据运行期按需</strong>。回到懒人图书馆的比喻：索引卡片（元数据）随身携带，翻目录永远即时；书（完整数据）放在仓库，点名才取——第 5 章的三级缓存（内存、书架、仓库）就是取书的那套流程。第一版把整个仓库背在身上，市场拒收；第二版连目录都不带，断网就全瞎——两个极端各错一半。</p><h2 id="这条分界线划下去-账是这样平的" tabindex="-1">这条分界线划下去，账是这样平的 <a class="header-anchor" href="#这条分界线划下去-账是这样平的" aria-label="Permalink to &quot;这条分界线划下去，账是这样平的&quot;">​</a></h2><p><strong>启动账</strong>。扩展激活时加载的是几 MB 的元数据，而不是上百 MB 的图形数据。激活事件决定「什么时候开始付钱」，这一章的分界决定「开始付的时候付多少」——两者合起来，才是一个不拖慢启动的插件的全貌。惰性加载不是「以后再做」的拖延，而是把成本精确挪到使用发生的那一刻。</p><p><strong>流量账</strong>。用户一天用到几个集合？通常不超过十个。按需下载的总流量是「用过的集合」之和，全量打包则是「存在的集合」之和——差两三个数量级。CDN 侧也不用为每个用户全量服务。</p><p><strong>更新账</strong>。图标库天天在加新图标。数据若打进包里，更新图标要发扩展版本；数据在远端，图标库更新与扩展版本彻底解耦——扩展不升级，图标也常新。构建期/运行期的分界，同时也是「变更频率不同的东西别捆在一起发布」的工程原则。</p><p><strong>离线账</strong>。这是第二版翻车的地方，也是第 5 章磁盘缓存真正的价值：用过的集合都落了盘，断网后内存未命中的请求由磁盘兜住。离线体验不是「全有」或「全无」，而是「用过的都有」——对绝大多数工作流，这就够了。配上坏缓存跳过回源的容错，离线降级是平滑的。</p><p>分界线也不是只能划在「元数据 / 完整数据」之间。自定义图标库（第 11 章）走的是另一条路：团队自己的私有集合不大，又天天变，本地文件 + 热重载比「打包」和「远程」都合适。划线的依据始终是三个问题的答案：多重、何时用、多久变一次。</p><h2 id="数据流全景" tabindex="-1">数据流全景 <a class="header-anchor" href="#数据流全景" aria-label="Permalink to &quot;数据流全景&quot;">​</a></h2><p>把前六章的模块放进这条分界里，全书的数据流就完整了：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 拼版：数据流全景(示意,非代码)</span></span>
<span class="line"><span>┌─ 构建期 ─────────────────────────────┐</span></span>
<span class="line"><span>│ 图标世界 → 抽取元数据(id/名字清单) → 打包 │</span></span>
<span class="line"><span>└──────────────┬───────────────────────┘</span></span>
<span class="line"><span>               ↓ 激活时载入内存</span></span>
<span class="line"><span>┌─ 运行期 ─────────────────────────────┐</span></span>
<span class="line"><span>│ 识别/解析/补全 ←─ 元数据(常驻)          │</span></span>
<span class="line"><span>│ 装饰/悬停 ──→ 三级缓存 ──→ 渲染管线     │</span></span>
<span class="line"><span>│                内存 → 磁盘 → 远程下载   │</span></span>
<span class="line"><span>│                (断网时止步于磁盘)        │</span></span>
<span class="line"><span>└──────────────────────────────────────┘</span></span></code></pre></div><p>值得再看一眼的是：元数据与完整数据用同一个键（集合 id）衔接。识别阶段从元数据知道「有 mdi 这个集合、有 home 这个名字」，渲染阶段拿同一个 id 去缓存与远程取完整数据——键的贯通让两段数据各守其位又互不脱节。图标名在元数据里存在、完整数据里却没有（集合更新滞后）的窗口期，渲染端安静地跳过即可，第 4 章定下的「失败返回 undefined、不抛异常」约定在这里接住了最后一种错位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>构建期打包索引卡片，运行期按需取书：元数据轻、常驻、喂同步逻辑；完整数据重、按需、喂渲染。这条分界同时平了启动、流量、更新、离线四笔账，离线的答案是「用过的都有」而非「全都有」。至此识别与数据两段全部就绪，从下一章起进入智能段：把这些能力组装成装饰、补全、悬停——用户真正看见的三样东西。</p>`,19)])])}const g=s(t,[["render",i]]);export{u as __pageData,g as default};
